package studio.jiayu.neo;
import android.content.*;
import android.net.Uri;
import android.app.AlertDialog;
import android.os.StatFs;
import org.json.*;
import java.io.*;
import java.net.*;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.util.*;
/** Local model weights are app-private data, never bundled in project exports. */
final class LocalModels {
 final MainActivity a;volatile boolean running,cancelled;volatile JSONObject status=new JSONObject();
 LocalModels(MainActivity a){this.a=a;}
 static File directory(Context c){File f=new File(c.getFilesDir(),"local-models");f.mkdirs();return f;}
 static File modelFile(Context c,String id)throws Exception{if(!id.matches("[A-Za-z0-9_-]{1,80}"))throw new Exception("无效的模型标识");return new File(directory(c),id+".litertlm");}
 JSONArray list(){JSONArray out=new JSONArray();File[] fs=directory(a).listFiles();if(fs!=null)for(File f:fs)if(f.getName().endsWith(".json"))try{JSONObject m=new JSONObject(new String(MainActivity.readLimited(new FileInputStream(f),65536),StandardCharsets.UTF_8));File weight=modelFile(a,m.getString("id"));if(weight.isFile()){m.put("size",weight.length());out.put(m);}}catch(Exception ignored){}return out;}
 void progress(String stage,String name,long bytes,long total){try{status=new JSONObject().put("running",running).put("stage",stage).put("name",name).put("bytes",bytes).put("total",total);a.event("localModelProgress",status);}catch(Exception ignored){}}
 void inspect(JSONObject p){if(running){a.toast("请等待模型下载完成");return;}a.worker.execute(()->{try{String repo=p.optString("repo").trim();if(!repo.matches("[A-Za-z0-9_.-]+/[A-Za-z0-9_.-]+"))throw new Exception("请输入 Hugging Face 的组织/仓库名");String token=p.optString("token").trim();if(!token.isEmpty())a.vault.put("hf-download",token);byte[] raw;HttpURLConnection c=open("https://huggingface.co/api/models/"+repo+"?blobs=true",0);try(InputStream in=c.getInputStream()){raw=MainActivity.readLimited(in,4*1024*1024);}finally{c.disconnect();}JSONObject model=new JSONObject(new String(raw,StandardCharsets.UTF_8));JSONArray files=new JSONArray(),siblings=model.getJSONArray("siblings");for(int i=0;i<siblings.length();i++){JSONObject f=siblings.getJSONObject(i);String path=f.optString("rfilename");if(path.endsWith(".litertlm")){JSONObject lfs=f.optJSONObject("lfs");if(lfs!=null)files.put(new JSONObject().put("file",path).put("size",f.optLong("size",lfs.optLong("size"))).put("sha256",lfs.optString("sha256")));}}a.event("localModelCatalog",new JSONObject().put("repo",repo).put("revision",model.getString("sha")).put("files",files));}catch(Exception e){a.event("error","模型列表读取失败（"+e.getClass().getSimpleName()+"）；检查网络和仓库访问许可。受限模型需先接受许可并填写只读令牌。");}});}
 HttpURLConnection open(String url,long offset)throws Exception{
  for(int i=0;i<8;i++){URL u=new URL(url);if(!u.getProtocol().equals("https")||u.getUserInfo()!=null)throw new IOException("模型下载仅支持 HTTPS");HttpURLConnection c=(HttpURLConnection)u.openConnection();c.setInstanceFollowRedirects(false);c.setConnectTimeout(20000);c.setReadTimeout(45000);if(offset>0)c.setRequestProperty("Range","bytes="+offset+"-");if(u.getHost().equals("huggingface.co")){String token=a.vault.get("hf-download");if(!token.isEmpty())c.setRequestProperty("Authorization","Bearer "+token);}int code=c.getResponseCode();if(code>=300&&code<400){String location=c.getHeaderField("Location");c.disconnect();url=new URL(u,location).toString();continue;}if(code!=200&&code!=206){c.disconnect();throw new IOException("下载 HTTP "+code);}return c;}throw new IOException("下载重定向次数过多");
 }
 void download(JSONObject p)throws Exception{
  if(running)throw new Exception("已有模型正在下载");String repo=p.getString("repo"),rev=p.getString("revision"),file=p.getString("file"),hash=p.getString("sha256");if(!repo.matches("[A-Za-z0-9_.-]+/[A-Za-z0-9_.-]+")||!rev.matches("[a-f0-9]{40}")||!file.matches("[A-Za-z0-9_./-]+")||file.contains("..")||!file.endsWith(".litertlm")||!hash.matches("[a-f0-9]{64}"))throw new Exception("模型文件信息无效，请重新读取仓库");long size=p.getLong("size");if(size<=0||size>20L*1024*1024*1024)throw new Exception("请选择20 GB以内的端侧模型");String id="hf-"+hash.substring(0,24);File partial=new File(directory(a),id+".part");if(new StatFs(directory(a).getPath()).getAvailableBytes()<size-partial.length()+512L*1024*1024)throw new Exception("空间不足，需保留下载空间和运行缓存");
  running=true;cancelled=false;progress("下载中",file,partial.length(),size);a.worker.execute(()->{try{long offset=partial.length();String url="https://huggingface.co/"+repo+"/resolve/"+rev+"/"+file;HttpURLConnection c=open(url,offset);try{boolean append=offset>0&&c.getResponseCode()==206;if(append&&!c.getHeaderField("Content-Range").startsWith("bytes "+offset+"-"))throw new IOException("断点校验失败");if(!append)offset=0;long n=offset,last=0;try(InputStream in=c.getInputStream();FileOutputStream out=new FileOutputStream(partial,append)){byte[] b=new byte[1024*1024];int count;while((count=in.read(b))!=-1){if(cancelled)throw new InterruptedIOException("已暂停");n+=count;if(n>size)throw new IOException("文件长度超出元数据");out.write(b,0,count);if(System.currentTimeMillis()-last>700){progress("下载中",file,n,size);last=System.currentTimeMillis();}}}if(n!=size)throw new IOException("下载未完成");}finally{c.disconnect();}progress("校验 SHA256",file,size,size);if(!hash(partial).equals(hash)){partial.delete();throw new IOException("哈希不匹配，请重新下载");}File destination=modelFile(a,id);if(!partial.renameTo(destination))throw new IOException("保存失败");JSONObject meta=new JSONObject().put("id",id).put("name",repo.substring(repo.indexOf('/')+1)).put("repo",repo).put("revision",rev).put("file",file).put("sha256",hash).put("officialPreset",repo.equals("litert-community/gemma-4-E4B-it-litert-lm"));writeMeta(meta);a.event("localModelsChanged",list());progress("已安装",file,size,size);}catch(Exception e){progress(cancelled?"已暂停，可继续":"下载失败，可重试",file,partial.length(),size);}finally{running=false;try{status.put("running",false);a.event("localModelProgress",status);}catch(Exception ignored){}}});
 }
 static String hash(File f)throws Exception{MessageDigest h=MessageDigest.getInstance("SHA-256");try(InputStream in=new FileInputStream(f)){byte[]b=new byte[1024*1024];int n;while((n=in.read(b))!=-1)h.update(b,0,n);}StringBuilder s=new StringBuilder();for(byte b:h.digest())s.append(String.format("%02x",b&255));return s.toString();}
 void writeMeta(JSONObject meta)throws Exception{try(OutputStream out=new FileOutputStream(new File(directory(a),meta.getString("id")+".json"))){out.write(meta.toString().getBytes(StandardCharsets.UTF_8));}}
 void importFile(Uri uri){if(running){a.toast("请等待当前下载结束");return;}running=true;cancelled=false;progress("导入中","本地模型",0,0);a.worker.execute(()->{File part=new File(directory(a),"import.part");try{try(InputStream in=a.getContentResolver().openInputStream(uri);OutputStream out=new FileOutputStream(part)){byte[]b=new byte[1024*1024];int n;long bytes=0,last=0;while((n=in.read(b))!=-1){if(cancelled)throw new InterruptedIOException();bytes+=n;if(bytes>20L*1024*1024*1024)throw new IOException("模型过大");out.write(b,0,n);if(System.currentTimeMillis()-last>700){progress("导入中","本地模型",bytes,0);last=System.currentTimeMillis();}}}String sha=hash(part),id="local-"+sha.substring(0,24);if(!part.renameTo(modelFile(a,id)))throw new IOException();JSONObject meta=new JSONObject().put("id",id).put("name","自定义模型 · "+sha.substring(0,8)).put("sha256",sha).put("officialPreset",false);writeMeta(meta);a.event("localModelsChanged",list());progress("已导入","自定义模型",0,0);}catch(Exception e){part.delete();progress("导入失败","请选择 LiteRT-LM .litertlm 模型",0,0);}finally{running=false;try{status.put("running",false);a.event("localModelProgress",status);}catch(Exception ignored){}}});}
 void select(JSONObject p)throws Exception{String id=p.getString("id");if(!modelFile(a,id).isFile())throw new Exception("模型文件不存在");JSONObject meta=null;JSONArray all=list();for(int i=0;i<all.length();i++)if(all.getJSONObject(i).optString("id").equals(id))meta=all.getJSONObject(i);if(meta==null)throw new Exception("模型信息不存在");int context=p.optInt("contextTokens",meta.optBoolean("officialPreset")?32768:8192),output=p.optInt("maxTokens",2048),topK=p.optInt("topK",64);double temp=p.optDouble("temperature",1),topP=p.optDouble("topP",.95);String backend=p.optString("backend","gpu");if(context<1024||context>32768||output<64||output>context-512||topK<1||topK>256||temp<0||temp>2||topP<=0||topP>1||!Arrays.asList("gpu","cpu").contains(backend))throw new Exception("参数超出范围，输出至少为输入预留512 Token");JSONObject profile=new JSONObject().put("id",id).put("name",meta.optString("name")+" · 本地").put("protocol","local").put("endpoint","local://device").put("model",id).put("contextTokens",context).put("maxTokens",output).put("topK",topK).put("topP",topP).put("temperature",temp).put("backend",backend).put("mtp",p.optBoolean("mtp",true)).put("localThinking",p.optBoolean("localThinking",false));a.upsert("profiles",profile);a.sendState();a.event("profileSaved",new JSONObject().put("id",id).put("next","local"));}
 void delete(String id)throws Exception{if(running||a.active!=null)throw new Exception("请先结束下载或生成");File f=modelFile(a,id);new AlertDialog.Builder(a).setTitle("删除本地模型文件？").setMessage("对话和项目保留；以后可重新下载。").setNegativeButton("取消",null).setPositiveButton("删除",(d,n)->{try{if(!f.delete()&&f.exists())throw new IOException();new File(directory(a),id+".json").delete();a.remove("profiles",id);a.sendState();a.event("localModelsChanged",list());}catch(Exception e){a.toast("模型删除失败");}}).show();}
}
